// Match test for the committed genoffice tool-schema file (G6-09 W10, G7-12 residual R2, Q4).
//
//   node --test scripts/office/g5g6g7/genoffice-tool-schemas.test.mjs
//
// docs/office/g5g6g7/genoffice-tool-schemas.json is generated by the fork's extractor
// (`--emit-schemas`, see genoffice-tool-schemas.README.md) at the same rev as the extract block of
// docs/office/g5g6g7/genoffice-tools.md. Like the G7-06 extractor check, this test does not run the extractor: it
// holds the committed file to the committed block (same rev, same tools per module) and to the harness that reads it
// (holdout-backend.mjs, `--tool-schemas` semantics), so a re-pin of the table without a regenerated file fails here.

import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';

import { committedBlockLines, parseExtractBlock } from './g7-06/extractor-check.mjs';
import { frameToolCounts, offeredTools, TOOL_OPS, toolCatalogue, toolSurface } from './holdout-backend.mjs';

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../..');
const SCHEMAS_FILE = path.join(repoRoot, 'docs/office/g5g6g7/genoffice-tool-schemas.json');
const TOOLS_DOC = path.join(repoRoot, 'docs/office/g5g6g7/genoffice-tools.md');
const MODULES = ['docs', 'sheets', 'slides', 'pdf', 'markdown', 'html'];
const RUNTIME_MARK = '[generated at runtime]';

// Tools whose description the frame builds by calling product code at runtime (opNames(), buildOpsGuide(), ...). The
// file offers them with the real inputSchema and the literal description text plus the runtime marker. A new entry
// here is a decision (the holdout then runs that tool with a reduced description): it must be reviewed, not absorbed.
const PARTIAL_DESCRIPTION_TOOLS = [
  'docs/apply_ops',
  'markdown/apply_ops',
  'pdf/apply_ops',
  'sheets/load_guide',
  'slides/apply_ops',
  'slides/load_guide',
];

const schemaBytes = fs.readFileSync(SCHEMAS_FILE);
const file = JSON.parse(schemaBytes.toString('utf8'));
const block = committedBlockLines(fs.readFileSync(TOOLS_DOC, 'utf8'));
const committed = parseExtractBlock(block);
const sha256Hex = (value) => crypto.createHash('sha256').update(value).digest('hex');

const canonical = (value) => {
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
  return `{${Object.keys(value)
    .sort()
    .map((k) => `${JSON.stringify(k)}:${canonical(value[k])}`)
    .join(',')}}`;
};

const namesByModule = (rows) => {
  const out = {};
  for (const module of MODULES) out[module] = [];
  for (const row of rows) if (out[row.module]) out[row.module].push(row.tool ?? row.name);
  for (const module of MODULES) out[module].sort();
  return out;
};

test('the file header pins the same fork rev and the same mechanical block as genoffice-tools.md', () => {
  assert.ok(block, 'the extract block markers are present in genoffice-tools.md');
  assert.equal(file.header.kind, 'genoffice-tool-schemas');
  assert.equal(file.header.version, 1);
  assert.equal(file.header.rev, committed.rev, 'header rev = the extract block rev');
  // the extractor's stdout is the block lines plus a final newline: hash it exactly as `--emit-schemas` did
  assert.equal(file.header.mechanicalBlockSha256, sha256Hex(`${block.join('\n')}\n`));
});

test('the file lists exactly the tool names of the committed extract block, module by module', () => {
  const fromBlock = namesByModule(committed.rows);
  const fromCatalogue = namesByModule(file.catalogue);
  assert.deepEqual(fromCatalogue, fromBlock);
  for (const module of MODULES) {
    assert.equal(file.header.counts[module], fromBlock[module].length, `${module}: header count`);
  }
  // one catalogue entry per table row (agent-core rows included), and each row's own hash cell is carried
  assert.equal(file.catalogue.length, committed.rows.length);
  const hashes = new Map(committed.rows.map((r) => [`${r.module}|${r.tool}|${r.source}`, r.hash]));
  for (const entry of file.catalogue) {
    assert.equal(entry.tableHash, hashes.get(`${entry.module}|${entry.name}|${entry.source}`), `${entry.module}/${entry.name}`);
  }
});

test('every tool is offered with its real schema; the partial descriptions are exactly the reviewed ones', () => {
  for (const entry of file.catalogue) {
    assert.equal(entry.offered, true, `${entry.module}/${entry.name} is not offered: ${entry.reason}`);
    assert.equal(entry.schemaComplete, true, `${entry.module}/${entry.name}: ${entry.reason}`);
  }
  for (const module of MODULES) {
    assert.deepEqual(
      file[module].map((t) => t.function.name).sort(),
      namesByModule(committed.rows)[module],
      `${module}: the module array offers every table row`,
    );
    for (const tool of file[module]) {
      const { name, description, parameters } = tool.function;
      assert.equal(tool.type, 'function');
      assert.deepEqual(Object.keys(tool), ['type', 'function'], `${module}/${name}: nothing but the schema is sent to a model`);
      assert.ok(typeof description === 'string' && description.length > 0, `${module}/${name}: description`);
      assert.ok(parameters && parameters.type === 'object', `${module}/${name}: parameters`);
      const entry = file.catalogue.find((e) => e.module === module && e.name === name);
      assert.equal(sha256Hex(canonical(parameters)), entry.inputSchemaSha256, `${module}/${name}: schema hash`);
    }
  }
  const partial = file.catalogue.filter((e) => !e.descriptionComplete).map((e) => `${e.module}/${e.name}`);
  assert.deepEqual(partial.sort(), PARTIAL_DESCRIPTION_TOOLS);
  for (const key of PARTIAL_DESCRIPTION_TOOLS) {
    const [module, name] = key.split('/');
    const tool = file[module].find((t) => t.function.name === name);
    assert.ok(tool.function.description.includes(RUNTIME_MARK), `${key}: the runtime marker stands where the code ran`);
  }
  // no other description carries the marker, and nothing unresolved leaked into the file as text
  for (const module of MODULES) {
    for (const tool of file[module]) {
      if (PARTIAL_DESCRIPTION_TOOLS.includes(`${module}/${tool.function.name}`)) continue;
      assert.ok(!tool.function.description.includes(RUNTIME_MARK), `${module}/${tool.function.name}`);
    }
  }
  assert.ok(!schemaBytes.toString('utf8').includes('unresolved:'), 'no unresolved cell inside the schemas');
});

test('holdout-backend loads the file with --tool-schemas semantics and offers every mapped tool a real schema', () => {
  const catalogue = toolCatalogue(file);
  const surface = toolSurface(catalogue, { fileSha256: sha256Hex(schemaBytes), frameTotals: frameToolCounts() });
  for (const module of MODULES) {
    const mapped = Object.keys(TOOL_OPS[module]).sort();
    const offered = catalogue[module];
    assert.deepEqual(offered.map((t) => t.function.name).sort(), mapped, `${module}: the harness offers every mapped tool`);
    assert.match(surface[module].source, /^file:[0-9a-f]{64}$/, `${module}: no tool is name-only or from the dev set`);
    assert.equal(surface[module].offered, mapped.length);
    assert.equal(surface[module].frameTotal, file.header.counts[module]);
    // the offered tool is the file's own object: a real schema, never the name-only stand-in
    for (const tool of offered) {
      const own = file[module].find((t) => t.function.name === tool.function.name);
      assert.ok(own, `${module}/${tool.function.name} is in the file`);
      assert.deepEqual(tool, own);
      assert.notEqual(tool.function.description, `Tool ${tool.function.name} of the ${module} module of the open document.`);
    }
    // what the file describes beyond the mapping is reported, not offered (mapping more is g6-ai_server's, not this file's)
    assert.equal(surface[module].droppedFromFile.length, file[module].length - mapped.length);
  }
  // end to end for one case shape: the tools a case is offered come from the file
  const caseDoc = { fixtures: [{ id: 'fx-md-brief' }], tools: { required: [] } };
  const tools = offeredTools(caseDoc, catalogue);
  assert.deepEqual(tools.map((t) => t.function.name).sort(), Object.keys(TOOL_OPS.markdown).sort());
});
